def _parse_brick_size(size_str: str):
    """تحليل سلسلة المقاس 'L×W×H' إلى أرقام عشرية (l_cm, w_cm, h_cm)."""
    try:
        parts = [float(x.strip()) for x in size_str.replace("×", "x").split("x")]
        if len(parts) == 3:
            return parts[0], parts[1], parts[2]
    except Exception:
        pass
    return 25.0, 12.0, 6.0


