                    st.session_state[f"m15_cb_top_{bid}"] = True
                    st.session_state[f"m15_cb_bot_{bid}"] = True
                    st.session_state[f"m15_cb_left_{bid}"] = True
                    st.session_state[f"m15_cb_right_{bid}"] = True
