def _apply_3d_opening_move(payload_str=None):
    """
    مزامنة التعديلات الواردة من العارض ثلاثي الأبعاد 3D (تحريك الأبواب والشبابيك).
    تستقبل payload_str مباشرة من الـ React bridge أو query param 'm15_op_move'.
    وتقوم بتحديث موقع الفتحة في session_state وحفظ الإعدادات دون إعادة تحميل الصفحة.
    """
    val = payload_str
    if not val:
        val = st.session_state.get("m15_3d_sync_input")
    from_query = False
    if not val and "m15_op_move" in st.query_params:
        val = st.query_params["m15_op_move"]
        from_query = True

    if val:
        try:
            data = json.loads(val) if isinstance(val, str) else val
            action = str(data.get("action", "")).lower()
            op_type = str(data.get("type", "")).lower()

            if action == "delete_wall" or op_type == "delete_wall":
                wall_list = data.get("wall")
                if wall_list and len(wall_list) == 4:
                    wk = tuple(int(x) for x in wall_list)
                    removed_walls = st.session_state.get("m15_wall_removed", set())
                    if not isinstance(removed_walls, set):
                        removed_walls = set(removed_walls)
                    removed_walls.add(wk)
                    st.session_state["m15_wall_removed"] = removed_walls

                    # تحديد الحائط المحذوف في سيلكت بوكس القسم 3 لسرعة استعراضه واستعادته
                    all_walls = _get_all_walls()
                    if wk in all_walls:
                        st.session_state["m15_sel_wall"] = all_walls.index(wk) + 1

                    st.session_state.pop("m15_plan_png_b64", None)
                    try:
                        st.session_state["m15_3d_sync_input"] = ""
                    except Exception:
                        pass

                    if from_query:
                        if "m15_op_move" in st.query_params:
                            try:
                                del st.query_params["m15_op_move"]
                            except Exception:
                                pass
                        if "module" in st.query_params:
                            try:
                                del st.query_params["module"]
                            except Exception:
                                pass

                    save_settings()
                    cm = _get_col_name_map()
                    wm = _get_wall_name_map()
                    w_name = data.get("name") or _wall_display_label(wk, cm, wm)
                    st.toast(f"🗑️ تم حذف الحائط ({w_name}) وحفظه في قسم الحوائط لإمكانية استعادته!", icon="🗑️")
                    st.rerun()
                return

            if action == "delete_column" or op_type == "delete_column":
                col_coords = data.get("col")
                if col_coords and len(col_coords) == 2:
                    ci, cj = int(col_coords[0]), int(col_coords[1])
                    _record_col_deletion(ci, cj)
                    removed_cols = st.session_state.get("m15_col_removed", set())
                    if not isinstance(removed_cols, set):
                        removed_cols = set(removed_cols)
                    removed_cols.add((ci, cj))
                    st.session_state["m15_col_removed"] = removed_cols

                    all_cols = _get_all_columns()
                    if (ci, cj) in all_cols:
                        st.session_state["m15_sel_col"] = all_cols.index((ci, cj))

                    st.session_state["m15_col_restore_expander_open"] = True
                    st.session_state.pop("m15_plan_png_b64", None)
                    try:
                        st.session_state["m15_3d_sync_input"] = ""
                    except Exception:
                        pass

                    if from_query:
                        if "m15_op_move" in st.query_params:
                            try:
                                del st.query_params["m15_op_move"]
                            except Exception:
                                pass
                        if "module" in st.query_params:
                            try:
                                del st.query_params["module"]
                            except Exception:
                                pass

                    save_settings()
                    cn = _get_col_name_map()
                    c_name = data.get("name") or cn.get((ci, cj), f"C({ci+1},{cj+1})")
                    st.toast(f"🗑️ تم حذف العمود ({c_name}) وحفظه في قسم استعادة الأعمدة!", icon="🗑️")
                    st.rerun()
                return

            if action == "delete_window" or op_type == "delete_window":
                win_id = data.get("id")
                win_name = data.get("name", "الشباك")
                if win_id:
                    _remove_opening_by_id(win_id, "win")
                    st.session_state.pop("m15_plan_png_b64", None)
                    try:
                        st.session_state["m15_3d_sync_input"] = ""
                    except Exception:
                        pass
                    if from_query:
                        if "m15_op_move" in st.query_params:
                            try: del st.query_params["m15_op_move"]
                            except Exception: pass
                        if "module" in st.query_params:
                            try: del st.query_params["module"]
                            except Exception: pass
                    save_settings()
                    st.toast(f"🗑️ تم حذف الشباك ({win_name}) وحفظه في قسم استعادة الشبابيك والأبواب!", icon="🗑️")
                    st.rerun()
                return

            if action == "delete_door" or op_type == "delete_door":
                door_id = data.get("id")
                door_name = data.get("name", "الباب")
                if door_id:
                    _remove_opening_by_id(door_id, "door")
                    st.session_state.pop("m15_plan_png_b64", None)
                    try:
                        st.session_state["m15_3d_sync_input"] = ""
                    except Exception:
                        pass
                    if from_query:
                        if "m15_op_move" in st.query_params:
                            try: del st.query_params["m15_op_move"]
                            except Exception: pass
                        if "module" in st.query_params:
                            try: del st.query_params["module"]
                            except Exception: pass
                    save_settings()
                    st.toast(f"🗑️ تم حذف الباب ({door_name}) وحفظه في قسم استعادة الشبابيك والأبواب!", icon="🗑️")
                    st.rerun()
                return

            op_id = data.get("id")
            wall_list = data.get("wall")
            new_pos = float(data.get("pos", 0.0))
            if wall_list and len(wall_list) == 4 and op_id:
                wk = tuple(wall_list)
                found = False
                # 1. Primary lookup by op_type
                if op_type in ("win", "window"):
                    win_dict = st.session_state.get("m15_windows", {})
                    for w in win_dict.get(wk, []):
                        if w.get("id") == op_id:
                            w["pos_m"] = round(new_pos, 2)
                            st.session_state[f"m15_edit_wpos_{op_id}"] = round(new_pos, 2)
                            st.session_state[f"m15_mv_w_pos_{op_id}"] = round(new_pos, 2)
                            st.session_state["m15_active_move_dim"] = {
                                "op_id": op_id,
                                "kind": "win",
                                "kind_ar": "الشباك",
                                "name": w.get("name", op_id),
                                "wk": wk,
                                "pos_m": round(new_pos, 2),
                                "w_m": float(w.get("w_m", 1.0)),
                                "ts": time.time(),
                            }
                            found = True
                            break
                elif op_type in ("door", "doors"):
                    door_dict = st.session_state.get("m15_doors", {})
                    for d in door_dict.get(wk, []):
                        if d.get("id") == op_id:
                            d["pos_m"] = round(new_pos, 2)
                            st.session_state[f"m15_edit_dpos_{op_id}"] = round(new_pos, 2)
                            st.session_state[f"m15_mv_d_pos_{op_id}"] = round(new_pos, 2)
                            st.session_state["m15_active_move_dim"] = {
                                "op_id": op_id,
                                "kind": "door",
                                "kind_ar": "الباب",
                                "name": d.get("name", op_id),
                                "wk": wk,
                                "pos_m": round(new_pos, 2),
                                "w_m": float(d.get("w_m", 0.9)),
                                "ts": time.time(),
                            }
                            found = True
                            break

                # 2. Fallback search across both stores if not found
                if not found:
                    for w in st.session_state.get("m15_windows", {}).get(wk, []):
                        if w.get("id") == op_id:
                            w["pos_m"] = round(new_pos, 2)
                            st.session_state[f"m15_edit_wpos_{op_id}"] = round(new_pos, 2)
                            st.session_state[f"m15_mv_w_pos_{op_id}"] = round(new_pos, 2)
                            st.session_state["m15_active_move_dim"] = {
                                "op_id": op_id,
                                "kind": "win",
                                "kind_ar": "الشباك",
                                "name": w.get("name", op_id),
                                "wk": wk,
                                "pos_m": round(new_pos, 2),
                                "w_m": float(w.get("w_m", 1.0)),
                                "ts": time.time(),
                            }
                            found = True
                            break
                    if not found:
                        for d in st.session_state.get("m15_doors", {}).get(wk, []):
                            if d.get("id") == op_id:
                                d["pos_m"] = round(new_pos, 2)
                                st.session_state[f"m15_edit_dpos_{op_id}"] = round(new_pos, 2)
                                st.session_state[f"m15_mv_d_pos_{op_id}"] = round(new_pos, 2)
                                st.session_state["m15_active_move_dim"] = {
                                    "op_id": op_id,
                                    "kind": "door",
                                    "kind_ar": "الباب",
                                    "name": d.get("name", op_id),
                                    "wk": wk,
                                    "pos_m": round(new_pos, 2),
                                    "w_m": float(d.get("w_m", 0.9)),
                                    "ts": time.time(),
                                }
                                found = True
                                break

            if from_query:
                if "m15_op_move" in st.query_params:
                    try:
                        del st.query_params["m15_op_move"]
                    except Exception:
                        pass
                if "module" in st.query_params:
                    try:
                        del st.query_params["module"]
                    except Exception:
                        pass

            try:
                st.session_state["m15_3d_sync_input"] = ""
            except Exception:
                pass
            _resequence_openings()
            st.session_state.pop("m15_plan_png_b64", None)
            save_settings()
            st.toast(f"✅ تم اعتماد وحفظ موضع الفتحة ({new_pos:.2f}م) في الحصر بنجاح!", icon="💾")
        except Exception:
            if from_query:
                if "m15_op_move" in st.query_params:
                    try:
                        del st.query_params["m15_op_move"]
                    except Exception:
                        pass
                if "module" in st.query_params:
                    try:
                        del st.query_params["module"]
                    except Exception:
                        pass


def _trigger_browser_download(file_bytes: bytes, filename: str):
    """
    يقوم بتنزيل الملف عبر المتصفح مباشرة وفتح نافذة الحفظ (Save Dialog)
    باستخدام JavaScript و Blob بدون الحاجة لزر تحميل وسيط.
    """
    import streamlit.components.v1 as components
    b64 = base64.b64encode(file_bytes).decode("utf-8")
    js_code = f"""
    <script>
    (function() {{
        try {{
            var b64Data = "{b64}";
            var byteChars = atob(b64Data);
            var byteNums = new Array(byteChars.length);
            for (var i = 0; i < byteChars.length; i++) {{
                byteNums[i] = byteChars.charCodeAt(i);
            }}
            var byteArray = new Uint8Array(byteNums);
            var blob = new Blob([byteArray], {{type: "application/pdf"}});
            var blobUrl = URL.createObjectURL(blob);
            
            var targetDoc = (window.parent && window.parent.document) ? window.parent.document : document;
            var a = targetDoc.createElement("a");
            a.href = blobUrl;
            a.download = "{filename}";
            a.target = "_blank";
            targetDoc.body.appendChild(a);
            a.click();
            setTimeout(function() {{
                try {{ targetDoc.body.removeChild(a); }} catch(e) {{}}
                URL.revokeObjectURL(blobUrl);
            }}, 4000);
        }} catch(err) {{
            console.error("Auto download failed:", err);
            var aFallback = document.createElement("a");
            aFallback.href = "data:application/pdf;base64,{b64}";
            aFallback.download = "{filename}";
            document.body.appendChild(aFallback);
            aFallback.click();
        }}
    }})();
    </script>
    """
    components.html(js_code, height=0, width=0)


def _section_export_pdf():
    """
    قسم حفظ وتصدير مخرجات الموديول 15 (أعمال المباني والمحارة) كملف PDF وملف HTML مستقل.
    يقع بعد جميع أقسام الموديول.
    """
    from modules.report_generator import (
        generate_masonry_plaster_report_html,
        generate_masonry_plaster_concise_survey_report_html,
        html_to_pdf_bytes
    )
    from modules.settings import get_safe_profile_filename_prefix, get_active_profile_name

    active_proj = get_active_profile_name() or "Masonry_Plaster_Project"
    prefix = get_safe_profile_filename_prefix()

    # 1. إعداد مخطط المسقط الأفقي المصمم بصيغة Base64
    buf_plan = _draw_plan(with_dim=True)
    img_plan_b64 = base64.b64encode(buf_plan.getvalue()).decode("utf-8") if buf_plan else None

    # 2. حساب حصر المباني
    res_survey = _compute_survey(len_mode="clear")
    r12 = res_survey.get("rows_12", [])
    r25 = res_survey.get("rows_25", [])

    g12 = sum(r.get("المساحة الإجمالية (م2)", 0.0) for r in r12)
    op12 = sum(r.get("مساحة الفتحات (م2)", 0.0) for r in r12)
    n12 = sum(r.get("المساحة الصافية (م2)", 0.0) for r in r12)

    g25 = sum(r.get("المساحة الإجمالية (م2)", 0.0) for r in r25)
    op25 = sum(r.get("مساحة الفتحات (م2)", 0.0) for r in r25)
    n25 = sum(r.get("المساحة الصافية (م2)", 0.0) for r in r25)
    v25 = sum(r.get("حجم الطوب (م3)", 0.0) for r in r25)

    sand_12 = n12 * 0.025
    sand_25 = v25 * 0.200
    sand_net_masonry = sand_12 + sand_25
    sand_total_masonry = sand_net_masonry * 1.05

    cement_masonry_kg = sand_total_masonry * 350.0
    cement_masonry_tons = cement_masonry_kg / 1000.0
    cement_masonry_bags = math.ceil(cement_masonry_kg / 50.0) if cement_masonry_kg > 0 else 0

    brick_size_v = st.session_state.get("m15_brick_size", "25×12×6")
    mortar_v = float(st.session_state.get("m15_mortar_thickness_cm", 1.0))
    if brick_size_v == _CUSTOM_SIZE_LABEL:
        b_l = float(st.session_state.get("m15_brick_custom_l", 25.0))
        b_w = float(st.session_state.get("m15_brick_custom_w", 12.0))
        b_h = float(st.session_state.get("m15_brick_custom_h", 6.0))
    else:
        b_l, b_w, b_h = _parse_brick_size(brick_size_v)

    bricks_12 = _compute_brick_qty(n12, _WALL_THIN, b_l, b_w, b_h, mortar_v)
    bricks_25 = _compute_brick_qty(n25, _WALL_THICK, b_l, b_w, b_h, mortar_v)
    bricks_total = bricks_12 + bricks_25
    brick_type_display = st.session_state.get("m15_brick_type", "الطوب الأحمر الطفلي")
    brick_size_display = f"{b_l:.0f}×{b_w:.0f}×{b_h:.0f} سم" if brick_size_v == _CUSTOM_SIZE_LABEL else f"{brick_size_v} سم"

    # 3. حساب حصر المحارة
    p_res = _compute_plaster_survey()
    p_rows = p_res.get("rows", [])
    p_net_m2 = p_res.get("tot_net", 0.0)
    p_gross_m2 = p_res.get("tot_gross", 0.0)
    p_ded_m2 = p_res.get("tot_ded", 0.0)
    p_sand_m3 = p_res.get("tot_sand", 0.0)
    p_cement_tons = p_res.get("tot_cement_tons", 0.0)
    p_cement_bags = p_res.get("tot_cement_bags", 0)
    p_active_walls = p_res.get("active_walls_count", 0)
    deduction_rule_str = st.session_state.get("m15_plaster_deduction_rule_str", "الكود المصري ECP")

    # 4. إجماليات الخامات
    total_sand_all = sand_total_masonry + p_sand_m3
    total_cement_tons_all = cement_masonry_tons + p_cement_tons
    total_cement_bags_all = cement_masonry_bags + p_cement_bags

    # 5. حسابات التكاليف والأسعار
    p_brick_in = float(st.session_state.get("m15_price_brick_per_thousand", 2500.0))
    p_sand_in = float(st.session_state.get("m15_price_sand_per_m3", 200.0))
    p_cement_in = float(st.session_state.get("m15_price_cement_per_ton", 4000.0))
    p_plaster_labor_in = float(st.session_state.get("m15_price_plaster_labor_per_m2", 70.0))

    brick_thousands = round(bricks_total / 1000.0, 3)
    cost_brick = round(brick_thousands * p_brick_in, 2)
    cost_sand_masonry = round(sand_total_masonry * p_sand_in, 2)
    cost_cement_masonry = round(cement_masonry_tons * p_cement_in, 2)
    cost_masonry_total = round(cost_brick + cost_sand_masonry + cost_cement_masonry, 2)

    cost_plaster_labor = round(p_net_m2 * p_plaster_labor_in, 2)
    cost_sand_plaster = round(p_sand_m3 * p_sand_in, 2)
    cost_cement_plaster = round(p_cement_tons * p_cement_in, 2)
    cost_plaster_total = round(cost_plaster_labor + cost_sand_plaster + cost_cement_plaster, 2)

    grand_total_cost = round(cost_masonry_total + cost_plaster_total, 2)

    # 6. تفصيل الفتحات
    openings_detail_list = []
    removed_walls = st.session_state.get("m15_wall_removed", set())
    wm_op = _get_wall_name_map()
    cm_op = _get_col_name_map()
    for wk in _get_all_walls():
        if wk in removed_walls:
            continue
        thick = _get_wall_thickness(wk)
        wa, da = 0.0, 0.0
        wc, dc = 0, 0
        for wi in _get_wall_windows(wk):
            if not wi.get("removed", False):
                wa += float(wi.get("w_m", 1.0)) * float(wi.get("h_m", 1.2))
                wc += 1
        for di in _get_wall_doors(wk):
            if not di.get("removed", False):
                da += float(di.get("w_m", 0.9)) * float(di.get("h_m", 2.1))
                dc += 1
        if (wa + da) > 0:
            i1, j1, i2, j2 = wk
            wlbl = f"{wm_op.get(wk,'—')}: {cm_op.get((i1,j1),f'({i1+1},{j1+1})')}→{cm_op.get((i2,j2),f'({i2+1},{j2+1})')}"
            openings_detail_list.append({
                "حائط": wlbl,
                "سُمك": f"{thick} سم",
                "شبابيك (م²)": round(wa, 2),
                "أبواب (م²)": round(da, 2),
                "إجمالي الفتحات (م²)": round(wa + da, 2),
                "عدد شبابيك": wc,
                "عدد أبواب": dc,
            })

    # 7. صفوف الخامات
    brick_col_name = f"عدد الطوب ({brick_type_display} | {brick_size_display})"
    materials_rows_list = [
        {
            "بند الأعمال": f"مباني طوب سمك {_WALL_THIN} سم (نصف طوبة)",
            "الوحدة": "م² مسطح",
            "الكمية الصافية": round(n12, 2),
            "رمل صافي (م³)": round(sand_12, 2),
            "رمل مع الهالك 5% (م³)": round(sand_12 * 1.05, 2),
            "أسمنت (طن)": round((sand_12 * 1.05 * 350) / 1000.0, 2),
            "شكاير أسمنت (50كجم)": math.ceil((sand_12 * 1.05 * 350) / 50.0) if n12 > 0 else 0,
            brick_col_name: bricks_12,
        },
        {
            "بند الأعمال": f"مباني طوب سمك {_WALL_THICK} سم (طوبة كاملة)",
            "الوحدة": "م³ مكعب",
            "الكمية الصافية": round(v25, 2),
            "رمل صافي (م³)": round(sand_25, 2),
            "رمل مع الهالك 5% (م³)": round(sand_25 * 1.05, 2),
            "أسمنت (طن)": round((sand_25 * 1.05 * 350) / 1000.0, 2),
            "شكاير أسمنت (50كجم)": math.ceil((sand_25 * 1.05 * 350) / 50.0) if v25 > 0 else 0,
            brick_col_name: bricks_25,
        },
        {
            "بند الأعمال": "⬅️ إجمالي مواد أعمال المباني",
            "الوحدة": "—",
            "الكمية الصافية": "—",
            "رمل صافي (م³)": round(sand_net_masonry, 2),
            "رمل مع الهالك 5% (م³)": round(sand_total_masonry, 2),
            "أسمنت (طن)": round(cement_masonry_tons, 2),
            "شكاير أسمنت (50كجم)": cement_masonry_bags,
            brick_col_name: bricks_total,
        }
    ]
    if p_active_walls > 0:
        materials_rows_list.append({
            "بند الأعمال": "بياض محارة (سمك 2 سم شامل الطرطشة وبؤج وأوتار)",
            "الوحدة": "م² مسطح",
            "الكمية الصافية": round(p_net_m2, 2),
            "رمل صافي (م³)": round(p_sand_m3 / 1.05, 2),
            "رمل مع الهالك 5% (م³)": round(p_sand_m3, 2),
            "أسمنت (طن)": round(p_cement_tons, 2),
            "شكاير أسمنت (50كجم)": p_cement_bags,
            brick_col_name: "—",
        })
        materials_rows_list.append({
            "بند الأعمال": "✅ الإجمالي العام لكامل المشروع (مباني + محارة)",
            "الوحدة": "—",
            "الكمية الصافية": "—",
            "رمل صافي (م³)": round(sand_net_masonry + (p_sand_m3 / 1.05), 2),
            "رمل مع الهالك 5% (م³)": round(total_sand_all, 2),
            "أسمنت (طن)": round(total_cement_tons_all, 2),
            "شكاير أسمنت (50كجم)": total_cement_bags_all,
            brick_col_name: bricks_total,
        })

    masonry_summary_dict = {
        "n12": n12, "g12": g12, "op12": op12,
        "n25": n25, "g25": g25, "op25": op25, "v25": v25,
        "bricks_12": bricks_12, "bricks_25": bricks_25, "bricks_total": bricks_total,
        "sand_total_masonry": sand_total_masonry,
        "cement_masonry_tons": cement_masonry_tons,
        "cement_masonry_bags": cement_masonry_bags,
    }
    plaster_summary_dict = {
        "tot_net": p_net_m2, "tot_gross": p_gross_m2, "tot_ded": p_ded_m2,
        "tot_sand": p_sand_m3, "tot_cement_tons": p_cement_tons, "tot_cement_bags": p_cement_bags,
        "tot_op_gross": p_res.get("tot_op_gross", 0.0),
        "active_walls_count": p_active_walls,
    }
    total_materials_dict = {
        "total_sand_all": total_sand_all,
        "total_cement_tons_all": total_cement_tons_all,
        "total_cement_bags_all": total_cement_bags_all,
    }
    pricing_summary_dict = {
        "p_brick_in": p_brick_in, "p_sand_in": p_sand_in,
        "p_cement_in": p_cement_in, "p_plaster_labor_in": p_plaster_labor_in,
        "cost_brick": cost_brick, "cost_sand_masonry": cost_sand_masonry,
        "cost_cement_masonry": cost_cement_masonry, "cost_masonry_total": cost_masonry_total,
        "cost_plaster_labor": cost_plaster_labor, "cost_sand_plaster": cost_sand_plaster,
        "cost_cement_plaster": cost_cement_plaster, "cost_plaster_total": cost_plaster_total,
        "cost_sand_all": round(total_sand_all * p_sand_in, 2),
        "cost_cement_all": round(total_cement_tons_all * p_cement_in, 2),
        "grand_total_cost": grand_total_cost,
    }

    # 7. تجميع بيانات ومدخلات التصميم والمشروع بالكامل
    xs = st.session_state.get("m15_x_axes", [])
    ys = st.session_state.get("m15_y_axes", [])
    x_labels = ", ".join([f"X{i+1}" for i in range(len(xs))]) if xs else "—"
    y_labels = ", ".join([f"Y{j+1}" for j in range(len(ys))]) if ys else "—"
    x_spans = " | ".join([f"X{i+1} ({xs[i]:.2f}م)" for i in range(len(xs))]) if xs else "—"
    y_spans = " | ".join([f"Y{j+1} ({ys[j]:.2f}م)" for j in range(len(ys))]) if ys else "—"

    col_map = _get_col_name_map()
    cols_list = []
    for (i, j) in _get_active_columns():
        c_name = col_map.get((i, j), f"C({i+1},{j+1})")
        cw, ch = _get_col_wh(i, j)
        props = st.session_state.get("m15_col_props", {}).get((i, j), {})
        d_code = props.get("dir_code") or st.session_state.get("m15_col_dirs", {}).get((i, j), "NS")
        orient_lbl = "رأسي (N-S)" if d_code == "NS" else "أفقي (E-W)"
        sh_x = st.session_state.get("m15_col_shift_x", {}).get((i, j), "متمركز")
        sh_y = st.session_state.get("m15_col_shift_y", {}).get((i, j), "متمركز")
        shift_lbl = f"{sh_x} / {sh_y}" if (sh_x != "متمركز" or sh_y != "متمركز") else "متمركز"
        cols_list.append({
            "name": c_name,
            "axis_coord": f"X{i+1} / Y{j+1} ({xs[i]:.2f}, {ys[j]:.2f})" if i < len(xs) and j < len(ys) else f"({i+1},{j+1})",
            "b": round(min(cw, ch) * 100, 1),
            "t": round(max(cw, ch) * 100, 1),
            "orient": orient_lbl,
            "shift": shift_lbl
        })

    active_wins = _get_active_windows_list()
    win_models_dict = {}
    for (_, _, win, _) in active_wins:
        t_lbl = win.get("type_label") or win.get("name", "W1").split("-")[0]
        w_m = float(win.get("w_m", 1.0))
        h_m = float(win.get("h_m", 1.2))
        sill_m = float(win.get("sill_m", 1.0))
        if t_lbl not in win_models_dict:
            win_models_dict[t_lbl] = {
                "name": t_lbl,
                "w_m": w_m,
                "h_m": h_m,
                "area_m2": round(w_m * h_m, 2),
                "sill_m": sill_m,
                "count": 0
            }
        win_models_dict[t_lbl]["count"] += 1
    windows_models = list(win_models_dict.values())

    active_doors = _get_active_doors_list()
    door_models_dict = {}
    for (_, _, door, _) in active_doors:
        t_lbl = door.get("type_label") or door.get("name", "D1").split("-")[0]
        w_m = float(door.get("w_m", 0.9))
        h_m = float(door.get("h_m", 2.1))
        if t_lbl not in door_models_dict:
            door_models_dict[t_lbl] = {
                "name": t_lbl,
                "w_m": w_m,
                "h_m": h_m,
                "area_m2": round(w_m * h_m, 2),
                "count": 0
            }
        door_models_dict[t_lbl]["count"] += 1
    doors_models = list(door_models_dict.values())

    inputs_data = {
        "x_axes_info": xs,
        "y_axes_info": ys,
        "x_axes_labels": x_labels,
        "x_axes_spans": x_spans,
        "y_axes_labels": y_labels,
        "y_axes_spans": y_spans,
        "columns_list": cols_list,
        "windows_models": windows_models,
        "doors_models": doors_models,
    }

    # ── حساب بيانات المقايسة الشاملة وتفصيل كميات المواد لكل بند ──
    boq_calc_concise = _compute_plaster_boq_data(rule_key=st.session_state.get("m15_plaster_deduction_rule", "ecp"))
    openings_calc_concise = _get_openings_takeoff_data()
    t2_items_data_all = boq_calc_concise.get("t2_items_data", [])
    plaster_factor_val = boq_calc_concise.get("plaster_qty_factor", 1.00)
    grand_total_boq_cost = boq_calc_concise.get("grand_total_cost", 0.0)
    boq_items_list_all = boq_calc_concise.get("boq_items_list", [])

    boq_materials_dict_all = _compute_boq_items_materials_breakdown(
        t2_items_data=t2_items_data_all,
        plaster_qty_factor=plaster_factor_val,
        brick_l=b_l,
        brick_w=b_w,
        brick_h=b_h,
        mortar_cm=mortar_v,
    )
    boq_materials_list_all = boq_materials_dict_all.get("mat_items", [])

    bldg_specs_data_all = {
        "bldg_area": boq_calc_concise.get("bldg_area", 0.0),
        "perimeter": boq_calc_concise.get("perimeter", 0.0),
        "default_h": boq_calc_concise.get("default_h", 3.0),
        "parapet_h_m": boq_calc_concise.get("parapet_h_m", 1.4),
        "total_facade_h": boq_calc_concise.get("total_facade_h", 4.4),
        "parapet_thick_choice": boq_calc_concise.get("parapet_thick_choice", "حائط نصف طوبة"),
        "shafts_area_m2": boq_calc_concise.get("shafts_area_m2", 0.0),
        "sidewalk_w_m": float(st.session_state.get("m15_sidewalk_w_m", st.session_state.get("cw_sidewalk_w_m", 1.00))),
        "plaster_qty_factor": plaster_factor_val,
        "deduction_rule_str": deduction_rule_str,
    }

    # تقرير جميع المدخلات والمخرجات بالكامل (HTML فتح بالمتصفح شامل الرسم والحصر والتكلفة والمقايسة والمواد)
    report_html_all = generate_masonry_plaster_report_html(
        project_name=active_proj,
        img_plan_b64=img_plan_b64,
        masonry_summary=masonry_summary_dict,
        plaster_summary=plaster_summary_dict,
        total_materials=total_materials_dict,
        pricing_summary=pricing_summary_dict,
        walls_12_rows=r12,
        walls_25_rows=r25,
        openings_details=openings_detail_list,
        plaster_rows=p_rows,
        materials_rows=materials_rows_list,
        brick_type_display=brick_type_display,
        brick_size_display=brick_size_display,
        mortar_cm=mortar_v,
        deduction_rule_str=deduction_rule_str,
        include_inputs=True,
        inputs_data=inputs_data,
        boq_items_list=boq_items_list_all,
        boq_materials_list=boq_materials_list_all,
        plaster_qty_factor=plaster_factor_val,
        grand_total_boq_cost=grand_total_boq_cost,
        bldg_specs_data=bldg_specs_data_all,
    )

    # تقرير جداول الحصر المختصر PDF (المسقط الأفقي المصمم بأكبر مساحة + حصر الشبابيك والأبواب + حصر البنود المسعر + حصر البنود غير المسعر)
    report_html_concise = generate_masonry_plaster_concise_survey_report_html(
        project_name=active_proj,
        img_plan_b64=img_plan_b64,
        windows_models=openings_calc_concise.get("windows_models", []),
        doors_models=openings_calc_concise.get("doors_models", []),
        openings_wall_details=openings_calc_concise.get("wall_openings_details", []),
        boq_items=boq_calc_concise.get("boq_items_list", []),
        plaster_qty_factor=boq_calc_concise.get("plaster_qty_factor", 1.00),
        grand_total_cost=boq_calc_concise.get("grand_total_cost", 0.0),
        brick_type_display=brick_type_display,
        brick_size_display=brick_size_display,
        mortar_cm=mortar_v,
        deduction_rule_str=deduction_rule_str,
    )

    # تنسيق رسالة التحميل في منتصف الشاشة بخلفية معتمة
    spinner_modal_css = """
    <style>
    div[data-testid="stSpinner"] {
        position: fixed !important;
        top: 50% !important;
        left: 50% !important;
        transform: translate(-50%, -50%) !important;
        z-index: 9999999 !important;
        background: rgba(15, 23, 42, 0.96) !important;
        color: #ffffff !important;
        padding: 26px 48px !important;
        border-radius: 20px !important;
        border: 2px solid #3b82f6 !important;
        box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8), 0 0 30px rgba(59, 130, 246, 0.5) !important;
        font-size: 1.35rem !important;
        font-weight: 800 !important;
        text-align: center !important;
        direction: rtl !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        gap: 18px !important;
        min-width: 320px !important;
    }
    div[data-testid="stSpinner"] > div {
        border-top-color: #3b82f6 !important;
        border-right-color: #60a5fa !important;
        width: 38px !important;
        height: 38px !important;
        border-width: 4px !important;
        border-style: solid !important;
    }
    div[data-testid="stSpinner"]::before {
        content: "";
        position: fixed;
        top: -200vh;
        left: -200vw;
        width: 400vw;
        height: 400vh;
        background: rgba(0, 0, 0, 0.65);
        backdrop-filter: blur(5px);
        z-index: -1;
        pointer-events: all;
    }

    /* توحيد ألوان وخلفيات وخطوط أزرار التصدير: خلفية حمراء ونصوص بيضاء قابلة للنسخ */
    .st-key-m15_btn_export_pdf_concise button,
    .st-key-m15_btn_download_html button,
    div[class*="st-key-m15_btn_export_pdf_"] button,
    div[class*="st-key-m15_btn_download_html"] button {
        background: #dc2626 !important;
        background-color: #dc2626 !important;
        color: #ffffff !important;
        border: 1.5px solid #b91c1c !important;
        border-radius: 9px !important;
        font-weight: 800 !important;
        font-size: 1.05rem !important;
        padding: 10px 18px !important;
        box-shadow: 0 3px 10px rgba(220, 38, 38, 0.35) !important;
        transition: all 0.2s ease !important;
        user-select: text !important;
        -webkit-user-select: text !important;
    }
    .st-key-m15_btn_export_pdf_concise button *,
    .st-key-m15_btn_download_html button *,
    div[class*="st-key-m15_btn_export_pdf_"] button *,
    div[class*="st-key-m15_btn_download_html"] button * {
        color: #ffffff !important;
        font-weight: 800 !important;
        font-size: 1.05rem !important;
        user-select: text !important;
        -webkit-user-select: text !important;
        cursor: text !important;
    }
    .st-key-m15_btn_export_pdf_concise button:hover,
    .st-key-m15_btn_download_html button:hover,
    div[class*="st-key-m15_btn_export_pdf_"] button:hover,
    div[class*="st-key-m15_btn_download_html"] button:hover {
        background: #b91c1c !important;
        background-color: #b91c1c !important;
        color: #ffffff !important;
        border-color: #991b1b !important;
        box-shadow: 0 5px 16px rgba(220, 38, 38, 0.55) !important;
        transform: translateY(-1px) !important;
    }
    </style>
    """
    st.markdown(spinner_modal_css, unsafe_allow_html=True)

    pdf_fname_concise = f"{prefix}ECP_Masonry_Plaster_Concise_Survey.pdf"
    html_fname = f"{prefix}ECP_Masonry_Plaster_Full_Report.html"

    # 1. قسم "تصدير ملفات المدخلات والمخرجات" يظهر كـ Expander مطوي افتراضياً
    with st.expander("تصدير ملفات المدخلات والمخرجات", expanded=False):
        # زران رئيسيان متناسقان بعرض متساوٍ
        c_exp1, c_exp2 = st.columns([1, 1], gap="medium")

        with c_exp1:
            if st.button("📋 تصدير جداول الحصر المختصر PDF", key="m15_btn_export_pdf_concise", type="primary", use_container_width=True):
                with st.spinner("جاري تحميل الملف"):
                    pdf_bytes_concise = html_to_pdf_bytes(report_html_concise)
                if pdf_bytes_concise:
                    _trigger_browser_download(pdf_bytes_concise, pdf_fname_concise)
                    st.toast("✅ تم تصدير جداول الحصر المختصر PDF بنجاح وفتح نافذة الحفظ!", icon="📋")
                else:
                    st.error("تعذر إنشاء ملف الـ PDF تلقائياً، يمكنك تنزيل ملف الـ HTML وفتحه للطباعة كـ PDF مباشرة.")

        with c_exp2:
            st.download_button(
                label="🌐 حفظ التقرير بصيغة HTML (فتح بالمتصفح)",
                data=report_html_all.encode("utf-8"),
                file_name=html_fname,
                mime="text/html",
                key="m15_btn_download_html",
                use_container_width=True,
            )

        # 2. بانيل حفظ وتصدير تقرير ومخرجات الموديول 15 أسفل الأزرار بتنسيق من اليمين لليسار
        st.markdown(
            f"""<div style='background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%);
            border: 2px solid #3b82f6; border-radius: 14px; padding: 20px 24px; margin-top: 20px; margin-bottom: 12px;
            box-shadow: 0 8px 24px rgba(59, 130, 246, 0.25); text-align: right;' dir='rtl'>
            <div style='display:flex; align-items:center; justify-content:space-between; border-bottom: 1.5px solid rgba(59, 130, 246, 0.4); padding-bottom: 14px; margin-bottom: 16px; flex-wrap:wrap; gap:10px; direction:rtl;'>
                <div style='display:flex; align-items:center; gap:12px; text-align:right; direction:rtl;'>
                    <span style='font-size:1.8rem;'>💾</span>
                    <div style='text-align:right; direction:rtl;'>
                        <div style='font-weight:900; font-size:1.15rem; color:#ffffff; text-align:right; direction:rtl;'>
                            حفظ وتصدير تقرير ومخرجات الموديول 15 (ECP Masonry & Plaster Calculation Sheet)
                        </div>
                        <div style='font-size:0.83rem; color:#94a3b8; margin-top:2px; text-align:right; direction:rtl;'>
                            تصدير هندسي شامل ومتكامل: المخطط التنفيذي 2D + جداول الحصر + مقايسة الخامات + التسعير المالي
                        </div>
                    </div>
                </div>
                <span style='background: linear-gradient(135deg, #1d4ed8, #2563eb); color:#ffffff; font-size:0.80rem; font-weight:bold; padding:5px 16px; border-radius:20px; border:1px solid #60a5fa;'>
                    📄 تصدير رسمي معتمد (PDF & HTML)
                </span>
            </div>
            <div style='color:#cbd5e1; font-size:0.88rem; line-height:1.75; margin-bottom:16px; text-align:right; direction:rtl;'>
                يتضمن ملف التقرير المُصدَّر:
                <ul style='margin: 6px 20px 0 0; padding: 0; color:#e2e8f0; font-size:0.85rem; text-align:right; direction:rtl;'>
                    <li>📐 <b>المسقط الأفقي المصمم عالي الدقة (2D Plan):</b> موضحاً عليه المحاور، أبعاد الحوائط، الأعمدة، الشبابيك والأبواب، وأوجه المحارة المميزة بالألوان.</li>
                    <li>📋 <b>تقرير جداول الحصر المختصر (Concise Survey PDF):</b> المسقط الأفقي المصمم بأكبر مساحة، جدول حصر الشبابيك والأبواب، جدول حصر البنود المسعر، وجدول حصر البنود غير المسعر بدون أي تكلفة للتنفيذ والطرح.</li>
                    <li>🌐 <b>تقرير HTML الشامل لجميع المدخلات والمخرجات:</b> يعرض الرسم الهندسي التنفيذي عالي الدقة، جميع بيانات المحاور والأعمدة والفتحات وأبعاد المبنى والدروة، جداول الحصر التفصيلية، جدول مقايسة وحصر جميع بنود المشروع الـ 21 مع التوصيف والكميات والأسعار والتكلفة، وجدول حساب كميات المواد المستخدمة في كل بند (رمل، أسمنت، زلط، طوب، ومواد تكميلية).</li>
                    <li>🧱 <b>جداول حصر أعمال المباني التفصيلية:</b> لمباني 12 سم (م²) ومباني 25 سم (م³) متضمنة طول المحور، خصم الأعمدة الخالص، المساحات وعدد الطوب.</li>
                    <li>🎨 <b>جدول حصر أعمال المحارة (البياض):</b> لكل حائط مع الأوجه ومساحات الفتحات والخصم المعتمد طبقاً للكود المصري ECP والكميات.</li>
                    <li>📦 <b>مقايسة الخامات والمونة الشاملة:</b> رمل صافي وشامل الهالك 5%، أسمنت بالطن والشكاير، وعدد الطوب الإجمالي.</li>
                    <li>💰 <b>جدول التسعير والمقايسة المالية التقديرية:</b> إجمالي بند المباني، إجمالي بند المحارة، والإجمالي العام الشامل للمشروع.</li>
                </ul>
            </div>
        </div>""",
            unsafe_allow_html=True
        )


def render_masonry_plaster_module():

    """نقطة الدخول الرئيسية للـ Module 12."""
    st.session_state["nav_view"] = "module"
    st.session_state["in_module"] = True
    _handle_sync_payload()
    _init_state()

    def _on_openings_expander_change():
        is_now_open = bool(st.session_state.get("m15_openings_expander", False))
        st.session_state["m15_openings_expander_open"] = is_now_open
        if not is_now_open:
            st.session_state["m15_openings_win_wall_sel"] = 0
            st.session_state["m15_openings_door_wall_sel"] = 0
            st.session_state["m15_preview_opening"] = None
            st.session_state["m15_openings_keep_expanded"] = False
            st.session_state["m15_show_conflict_modal"] = False
            st.session_state["m15_conflict_errors"] = []

    is_openings_exp = bool(st.session_state.get("m15_openings_keep_expanded", False) or st.session_state.get("m15_show_conflict_modal", False))
    if is_openings_exp:
        st.session_state["m15_openings_expander_open"] = True

    is_add_wall_active = bool(st.session_state.get("m15_add_wall_mode", False))
    is_add_active = bool(st.session_state.get("m15_add_col_mode", False))
    is_restore_active = bool(st.session_state.get("m15_restore_col_mode", False))
    is_del_wall_active = bool(st.session_state.get("m15_del_wall_mode", False))
    is_add_win_active = bool(st.session_state.get("m15_add_win_mode", False))
    is_add_door_active = bool(st.session_state.get("m15_add_door_mode", False))

    # ── تفعيل تحديد ونسخ أسماء جميع الأزرار بالمرور بالماوس في كامل الموديول 15 ──
    st.markdown(
        """<style>
        /* تمكين تحديد ونسخ نصوص جميع الأزرار بالماوس في كامل Module 15 */
        button,
        button *,
        [data-testid="stButton"] button,
        [data-testid="stButton"] button *,
        [data-testid="stDownloadButton"] button,
        [data-testid="stDownloadButton"] button *,
        [data-testid="stBaseButton-secondary"],
        [data-testid="stBaseButton-secondary"] *,
        [data-testid="stBaseButton-primary"],
        [data-testid="stBaseButton-primary"] *,
        .stButton button,
        .stButton button *,
        .stDownloadButton button,
        .stDownloadButton button * {
            user-select: text !important;
            -webkit-user-select: text !important;
            -moz-user-select: text !important;
            -ms-user-select: text !important;
        }
        [data-testid="stButton"] button p,
        [data-testid="stButton"] button span,
        [data-testid="stDownloadButton"] button p,
        [data-testid="stDownloadButton"] button span,
        .stButton button p,
        .stButton button span,
        .stDownloadButton button p,
        .stDownloadButton button span,
        button p,
        button span {
            cursor: text !important;
            user-select: text !important;
            -webkit-user-select: text !important;
        }
        </style>""",
        unsafe_allow_html=True
    )
    components.html(
        """<script>
        (function() {
            function enableBtnTextCopy() {
                try {
                    var doc = (window.parent && window.parent.document) ? window.parent.document : document;
                    var buttons = doc.querySelectorAll('button, [data-testid="stButton"] button, [data-testid="stDownloadButton"] button');
                    buttons.forEach(function(btn) {
                        var txt = (btn.innerText || btn.textContent || '').trim();
                        if (txt) {
                            if (!btn.getAttribute('title')) {
                                btn.setAttribute('title', txt);
                            }
                            btn.style.userSelect = 'text';
                            btn.style.webkitUserSelect = 'text';
                            var inners = btn.querySelectorAll('p, span, div');
                            inners.forEach(function(el) {
                                el.style.userSelect = 'text';
                                el.style.webkitUserSelect = 'text';
                                el.style.cursor = 'text';
                            });
                        }
                    });
                } catch(e) {}
            }
            enableBtnTextCopy();
            setInterval(enableBtnTextCopy, 800);
        })();
        </script>""",
        height=0,
        width=0
    )

    # Hidden bridge text_input placed at top of module so it is always present in DOM
    st.markdown(
        """<style>
        div[data-testid="stTextInput"]:has(input[aria-label="m15_3d_sync_payload"]) {
            position: fixed !important;
            top: -9999px !important;
            left: -9999px !important;
            width: 1px !important;
            height: 1px !important;
            opacity: 0 !important;
            pointer-events: none !important;
            z-index: -9999 !important;
        }
        </style>""",
        unsafe_allow_html=True
    )
    sync_val = st.text_input(
        "m15_3d_sync_payload",
        value="",
        key="m15_3d_sync_input",
        on_change=_on_m15_3d_sync_input_change,
        label_visibility="collapsed"
    )
    queued_m15 = st.session_state.pop("_m15_queued_sync_payload", None)
    active_m15_val = queued_m15 or sync_val
    if active_m15_val:
        _handle_sync_payload(active_m15_val)
    elif "m15_op_move" in st.query_params:
        _handle_sync_payload(st.query_params["m15_op_move"])

    lc, rc = st.columns([0.82, 1.65], gap="medium")
    with lc:
        with st.expander("1️⃣ شبكة المحاور", expanded=False): _section_axes()
        is_add_wall_active = bool(st.session_state.get("m15_add_wall_mode", False))
        with st.expander("2️⃣ إسقاط الحوائط على المحاور", expanded=is_add_wall_active): _section_add_walls()
        with st.expander("🧱 اعمال الدروة والرصيف الجانبي", expanded=False):
            _section_parapet_works()
        with st.expander("➕ إضافة الأعمدة على المحاور", expanded=is_add_active): _section_add_columns()
        with st.expander("🛁 تحديد الحمامات والمطابخ والمناور", expanded=False):
            _section_bathrooms_kitchens()
        with st.expander("🚪🪟 نماذج الشبابيك والأبواب", expanded=False):
            _section_opening_types()
        with st.expander("4️⃣ إسقاط الشبابيك", expanded=is_add_win_active):
            _section_add_windows()
        with st.expander("5️⃣ إسقاط الأبواب", expanded=is_add_door_active):
            _section_add_doors()
        with st.expander("🚪 تعديل اتجاه فتح الابواب", expanded=False):
            _section_door_orientation()
        with st.expander("3️⃣ تحديد مواصفات وتعديل الحوائط", expanded=False): _section_walls()
        with st.expander("📐 ضبط اتجاهات وضرب الأعمدة", expanded=False): _section_column_orientations()
        with st.expander("🗑️ حذف الشبابيك والأبواب", expanded=False):
            _section_delete_openings()
        with st.expander("🗑️ حذف حوائط", expanded=is_del_wall_active): _section_delete_walls()
        with st.expander("🗑️ حذف الأعمدة", expanded=False): _section_columns()
        with st.expander("♻️ استعادة أعمدة (Interactive)", expanded=is_restore_active): _section_restore_columns()
        with st.expander("♻️ استعادة الشبابيك والأبواب المحذوفة", expanded=False):
            _section_restore_openings()
        with st.expander("7️⃣ تحديد حوائط المحارة", expanded=False):
            _section_plaster_walls()
        with st.expander("6️⃣ أنواع مقاسات الطوب", expanded=False):
            _section_brick_type()

    with rc:
        col_hdr_title, col_hdr_btn = st.columns([1.1, 1.25], gap="small")
        with col_hdr_title:
            st.markdown(
                "<div style='font-size:1.15rem;font-weight:700;color:#ffffff;line-height:36px;margin:0 0 10px 0;display:flex;align-items:center;' dir='rtl'>"
                "📐 المسقط الأفقي المصمم"
                "</div>",
                unsafe_allow_html=True
            )
        with col_hdr_btn:
            has_img = bool(st.session_state.get("m15_uploaded_image_b64"))
            btn_title = "🖼️ مسقط استرشادي مرفوع ✅ [ Ctrl + Alt + F ]" if has_img else "🖼️ تحميل صورة مسقط افقي استرشادي [ Ctrl + Alt + F ]"
            with st.popover(btn_title, use_container_width=True):
                _section_upload_image()

        pending_del = st.session_state.get("m15_pending_delete")
        cancel_all_int = st.session_state.get("m15_confirm_cancel_all_interior")
        if pending_del and pending_del.get("kind") != "wall":
            _render_floating_delete_panel(pending_del)
            kind_title = pending_del.get("title_kind", "العنصر")
            item_name = pending_del.get("name", "")
            step = pending_del.get("step", 1)

            if step == 1:
                st.markdown(
                    f"""<div style='background:rgba(239, 68, 68, 0.14); border:1.5px solid #ef4444; border-radius:8px; padding:10px 16px; margin-bottom:12px;' dir='rtl'>
                        <div style='display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px;'>
                            <div style='color:#fca5a5; font-weight:800; font-size:0.95rem;'>
                                🗑️ تم اختيار {kind_title} للحذف: <span style='color:#ffffff; text-decoration:underline;'>{item_name}</span>
                            </div>
                            <div style='color:#cbd5e1; font-size:0.82rem;'>
                                اختر "حذف نهائي" للمتابعة أو "إلغاء":
                            </div>
                        </div>
                    </div>""",
                    unsafe_allow_html=True
                )
                c_main1, c_main2 = st.columns(2)
                with c_main1:
                    if st.button("🗑️ حذف نهائي", key="m15_main_btn_del_final", type="primary", use_container_width=True):
                        pending_del["step"] = 2
                        st.session_state["m15_pending_delete"] = pending_del
                        st.rerun()
                with c_main2:
                    if st.button("✕ إلغاء", key="m15_main_btn_cancel_step1", use_container_width=True):
                        _cancel_pending_delete()
                        st.rerun()
            else:
                st.markdown(
                    f"""<div style='background:rgba(220, 38, 38, 0.22); border:2px solid #dc2626; border-radius:8px; padding:12px 16px; margin-bottom:14px;' dir='rtl'>
                        <div style='color:#fca5a5; font-weight:800; font-size:1rem; margin-bottom:4px;'>
                            ⚠️ رسالة تأكيد: هل أنت متأكد من الحذف النهائي لـ {kind_title} ({item_name})؟
                        </div>
                        <div style='color:#f8fafc; font-size:0.83rem;'>
                            تنبيه: لا يمكن التراجع عن هذا الإجراء بعد تنفيذه.
                        </div>
                    </div>""",
                    unsafe_allow_html=True
                )
                c_main_cf1, c_main_cf2 = st.columns(2)
                with c_main_cf1:
                    if st.button("✅ موافق علي الحذف", key="m15_main_btn_confirm_agree", type="primary", use_container_width=True):
                        _confirm_pending_delete(pending_del)
                with c_main_cf2:
                    if st.button("❌ إلغاء الحذف", key="m15_main_btn_cancel_del", use_container_width=True):
                        _cancel_pending_delete()
                        st.rerun()
        elif pending_del and pending_del.get("kind") == "wall":
            _cleanup_floating_delete_panel()

        elif cancel_all_int:
            _render_floating_plaster_cancel_panel()
        else:
            _cleanup_floating_delete_panel()

        active_dim = st.session_state.get("m15_active_move_dim")
        is_active_dim = False
        dim_elapsed = 0.0
        if active_dim and not pending_del:
            dim_elapsed = time.time() - float(active_dim.get("ts", 0.0))
            if dim_elapsed < 4.2:
                is_active_dim = True
            else:
                st.session_state.pop("m15_active_move_dim", None)
                active_dim = None

        if is_active_dim and active_dim:
            buf_dim = _draw_plan(with_dim=True)
            b64_dim = base64.b64encode(buf_dim.getvalue()).decode("utf-8")
            buf_clean = _draw_plan(with_dim=False)
            b64_clean = base64.b64encode(buf_clean.getvalue()).decode("utf-8")
            rem_ms = max(200, int((4.0 - dim_elapsed) * 1000))

            _render_interactive_plan(b64_override=b64_dim, b64_clean=b64_clean, rem_ms=rem_ms, box_mode=None)
        else:
            if is_add_active:
                _render_interactive_plan(box_mode="add")
            elif is_restore_active:
                _render_interactive_plan(box_mode="restore")
            elif is_del_wall_active:
                _render_interactive_plan(box_mode="delete_wall")
            elif pending_del:
                _render_interactive_plan(box_mode="delete_wall" if is_del_wall_active else None)
            elif is_add_wall_active:
                _render_interactive_plan(box_mode="add_wall")
            elif is_add_win_active:
                _render_interactive_plan(box_mode="add_window")
            elif is_add_door_active:
                _render_interactive_plan(box_mode="add_door")
            else:
                _render_interactive_plan(box_mode=None)

        _cmap_ui, _sheights_ui = _get_project_wall_height_colors()
        _h_spans_ui = " ".join([f"<span style='color:{_cmap_ui[h]};font-weight:bold;'>■ حائط ع={h:.2f}م</span>" for h in _sheights_ui])
        st.markdown(
            f"""<div style='font-size:0.78rem;margin-top:3px;display:flex;gap:12px;flex-wrap:wrap;'>
                {_h_spans_ui}
                <span style='color:{_CLR_WIN};font-weight:bold;'>■ شباك (W#)</span>
                <span style='color:{_CLR_DOOR};font-weight:bold;'>■ باب (D#)</span>
                <span style='color:{_CLR_COL};font-weight:bold;'>■ عمود (C#)</span>
                <span style='color:#EC4899;font-weight:bold;'>▨ وجه محارة (وردي)</span>
                <span style='color:#222;font-weight:bold;'>■ حائط (L#)</span>
                <span style='color:#888;font-weight:bold;'>┄ خط استرشادي (محذوف)</span>
            </div>""",unsafe_allow_html=True)

    st.divider()
    with st.expander(
        "🌐 3D (Data Processing & Rendering) — العارض ثلاثي الأبعاد التفاعلي",
        expanded=False,
        key="m15_3d_viewer_expander",
        on_change="rerun",
    ):
        if st.session_state.get("m15_3d_viewer_expander", False):
            _section_3d_viewer()
        else:
            st.info(
                "💡 **الوضع الخفيف (Lazy Loading):** قسم العارض ثلاثي الأبعاد في وضع السكون لتسريع أداء واستجابة البرنامج.\n\n"
                "انقر على عنوان هذا القسم لتوسيعه والبدء فورياً في معالجة البيانات وتحديث وعرض النموذج ثلاثي الأبعاد (3D Rendering)."
            )
    st.divider()
    with st.expander("جداول الحصر والتكلفة لجميع البنود", expanded=False):
        _section_plaster_boq()
    st.divider()
    _section_export_pdf()
    save_settings()
    _inject_floating_plan_viewer()


